pub fn find(cp: u21) ?*const Glyph {
    var lo: usize = 0;
    var hi: usize = glyphs.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (glyphs[mid].cp < cp) lo = mid + 1 else hi = mid;
    }
    if (lo < glyphs.len and glyphs[lo].cp == cp) return &glyphs[lo];
    return null;
}
